pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        // Set initial balance: give alice enough ether
        vm.deal(alice, 1);
        vm.deal(bob, 1);
        // Alice sends 1 wei to addToBalance — succeeds on both versions
        vm.prank(alice);
        c.addToBalance{value: 1}();
        // Alice now has balance 1. To overflow, she needs to add 2^256-1 wei.
        // But we only need to trigger a revert on reference. Send exactly 2^256-1 wei from alice.
        vm.deal(alice, type(uint256).max);
        vm.prank(alice);
        try c.addToBalance{value: type(uint256).max}() {
            // success on buggy version, overflow wraps alice balance to 0
        } catch {
            // revert on reference (alice balance stays 1)
        }
        // Now Bob tries to send 1 wei. On reference, this succeeds (no overflow for Bob).
        // On buggy version, the overflow left alice's balance = 0, and Bob's sends 1 wei, so his balance becomes 1.
        vm.prank(bob);
        c.addToBalance{value: 1}();
        // After these calls, on reference Bob's balance = 1; on buggy version Bob's balance = 1 as well.
        // Wait — we need a divergence. Actually both give Bob balance = 1.
        // We need to read a different balance. Let's check the contract's own balance.
        // Reference: Alice's 1 wei + Bob's 1 wei = 2 wei in contract.
        // Buggy: Alice's overflow wraps to 0, Bob's 1 wei = 1 wei in contract.
        // So address(c).balance differs: 2 vs 1.
        assertTrue(address(c).balance == 2);
    }
}

