pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.addToBalance{value: 1 ether}();

        // make the external call in withdrawBalance revert by using a contract that reverts on receive
        address attacker = address(new RevertingReceiver());
        vm.deal(attacker, 0);
        // transfer 0 eth to attacker via addToBalance to set attacker balance to 0
        vm.prank(attacker);
        c.addToBalance{value: 0}();

        // now attacker calls withdrawBalance - the external call to attacker will revert
        vm.prank(attacker);
        // In the reference, balance is set to 0 before the revert, so balance becomes 0.
        // In the buggy, the revert reverts the whole transaction, leaving balance unchanged (0).
        // We can catch the revert and check balance afterwards
        vm.prank(user); // user already has 1 eth balance
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        // The buggy version will revert, so ok is false; the reference also reverts, but balance is 0 in reference vs 1 eth in buggy? Wait: the reference sets balance to 0 then the external call to user (which is an EOA) succeeds, so withdraw succeeds. The buggy version: external call to user succeeds, then sets balance to 0. So they are the same for EOA. For a reverting receiver, the reference reverts after setting balance to 0, so actual balance is 0, but the whole tx reverts. The buggy version reverts without clearing balance, so balance remains 1 eth. Let's use a reverting receiver.
    }
}

contract RevertingReceiver {
    receive() external payable { revert(); }
}

