pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a contract that will reject ether (revert on receive)
        Reverter reverter = new Reverter();

        // Fund the reverter address with some ether so it can pay gas
        vm.deal(address(reverter), 1 ether);

        // User deposits 1 ETH via addToBalance
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.addToBalance{value: 1 ether}();

        // Prank as the reverter to call withdrawBalance; the external call will revert
        vm.prank(address(reverter));
        // Attempt to withdraw (balance is 0 but we force the call to revert via Reverter's fallback)
        // Actually we need the reverter to have balance; but we can't deposit as reverter because we just set up
        // Better: have the reverter first deposit via addToBalance, then withdraw
        // Reset: deposit as reverter
        vm.deal(address(reverter), 1 ether);
        vm.prank(address(reverter));
        c.addToBalance{value: 1 ether}();

        // Now withdraw as reverter; the reverter's receive reverts
        vm.prank(address(reverter));
        // We expect the call to revert overall
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok); // withdraw reverted

        // Now check getBalance for reverter
        // In reference: balance was set to 0 before the revert -> getBalance returns 0
        // In buggy: balance unchanged because the revert happened before the assignment -> getBalance returns 1 ether
        assertTrue(c.getBalance(address(reverter)) == 0);
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }
}

